package apigen

import (
	"bytes"
	"fmt"
	"go/format"
	"strconv"
	"strings"
)

// Header is the first line of the generated file.
func Header(commit string) string {
	return fmt.Sprintf("// Code generated by cmd/herdr-api-gen from %s %s at %s. DO NOT EDIT.", Repo, SchemaSource, commit)
}

// GenerateGo renders the Go types of a schema pinned at commit, gofmt'd.
func GenerateGo(schema []byte, commit string) ([]byte, error) {
	m, err := Load(schema)
	if err != nil {
		return nil, err
	}
	return m.Go(commit)
}

// Go renders the model as the source of package herdrapi.
func (m *Model) Go(commit string) ([]byte, error) {
	var body bytes.Buffer
	w := &writer{buf: &body}
	w.line("// Protocol and SchemaVersion are the pinned schema's header: the herdr")
	w.line("// protocol it describes and the version of the schema document.")
	w.line("const (")
	w.line("Protocol = %d", m.Protocol)
	w.line("SchemaVersion = %d", m.SchemaVersion)
	w.line(")")
	for _, name := range sortedKeys(m.Types) {
		t := m.Types[name]
		w.line("")
		switch t.Kind {
		case KindStruct:
			w.doc(t.Doc)
			w.structType(t.Name, t.Fields)
		case KindEnum:
			w.enum(t)
		case KindUnion:
			w.union(t)
		case KindRaw:
			w.doc(t.Doc)
			if t.Doc != "" {
				w.line("//")
			}
			w.line("// %s is untagged in the schema, so it stays raw JSON; decode the", t.Name)
			w.line("// alternative you expect. It is one of:")
			for _, a := range t.Alternatives {
				w.line("//   - %s", a)
			}
			w.line("type %s = json.RawMessage", t.Name)
		case KindRequest:
			w.request(t)
		case KindFlat:
			w.doc(t.Doc)
			if t.Doc != "" {
				w.line("//")
			}
			w.line("// Its payload is one of %s, flattened; properties they type", strings.Join(t.Alternatives, ", "))
			w.line("// differently are kept as a string or raw JSON.")
			w.structType(t.Name, t.Fields)
		}
	}
	src := body.String()
	var out bytes.Buffer
	out.WriteString(Header(commit) + "\n")
	out.WriteString("// To change a type, change it in herdr and move the pin (see README).\n\n")
	out.WriteString("package herdrapi\n\n")
	var imports []string
	if strings.Contains(src, "json.") {
		imports = append(imports, `"encoding/json"`)
	}
	if strings.Contains(src, "fmt.") {
		imports = append(imports, `"fmt"`)
	}
	if len(imports) > 0 {
		out.WriteString("import (\n" + strings.Join(imports, "\n") + "\n)\n\n")
	}
	out.WriteString(src)
	formatted, err := format.Source(out.Bytes())
	if err != nil {
		return nil, fmt.Errorf("generated Go does not parse: %w", err)
	}
	return formatted, nil
}

type writer struct{ buf *bytes.Buffer }

func (w *writer) line(format string, args ...any) {
	fmt.Fprintf(w.buf, format+"\n", args...)
}

// doc writes a schema description as a comment.
func (w *writer) doc(text string) {
	text = strings.TrimSpace(text)
	if text == "" {
		return
	}
	for _, l := range strings.Split(text, "\n") {
		if l = strings.TrimRight(l, " \t"); l == "" {
			w.line("//")
		} else {
			w.line("// %s", l)
		}
	}
}

func (w *writer) structType(name string, fields []Field) {
	if len(fields) == 0 {
		w.line("type %s struct{}", name)
		return
	}
	w.line("type %s struct {", name)
	for _, f := range fields {
		w.doc(f.Doc)
		tag := f.JSON
		if f.Omit != "" {
			tag += "," + f.Omit
		}
		w.line("%s %s `json:%s`", f.GoName, f.GoType, strconv.Quote(tag))
	}
	w.line("}")
}

func (w *writer) enum(t *Type) {
	w.doc(t.Doc)
	if t.Doc != "" {
		w.line("//")
	}
	w.line("// %s values a newer herdr adds decode as they are; see Known.", t.Name)
	w.line("type %s string", t.Name)
	w.line("")
	w.line("const (")
	for _, v := range t.Values {
		w.doc(v.Doc)
		w.line("%s %s = %s", v.GoName, t.Name, strconv.Quote(v.Value))
	}
	w.line(")")
	w.line("")
	w.line("// Known reports whether v is a value the pinned schema lists.")
	w.line("func (v %s) Known() bool {", t.Name)
	w.line("switch v {")
	names := make([]string, len(t.Values))
	for i, v := range t.Values {
		names[i] = v.GoName
	}
	w.line("case %s:", strings.Join(names, ", "))
	w.line("return true")
	w.line("}")
	w.line("return false")
	w.line("}")
}

func (w *writer) union(t *Type) {
	key := strconv.Quote(t.TagKey)
	w.doc(t.Doc)
	if t.Doc != "" {
		w.line("//")
	}
	w.line("// %s is tagged by %s: Value holds one of the %s* variant", t.Name, key, t.Name)
	w.line("// structs (as a value, not a pointer), or UnknownVariant for a tag the")
	w.line("// pinned schema does not list.")
	w.line("type %s struct {", t.Name)
	w.line("Value %sVariant", t.Name)
	w.line("}")
	w.line("")
	w.line("// %sVariant is implemented by every %s variant and by UnknownVariant.", t.Name, t.Name)
	w.line("type %sVariant interface {", t.Name)
	w.line("variant")
	w.line("is%s()", t.Name)
	w.line("}")
	w.line("")
	w.line("// Tag returns the %s of u's variant, or \"\" when u holds none.", key)
	w.line("func (u %s) Tag() string {", t.Name)
	w.line("if u.Value == nil {")
	w.line(`return ""`)
	w.line("}")
	w.line("return u.Value.variantTag()")
	w.line("}")
	w.line("")
	w.line("// MarshalJSON writes the variant with its %s tag.", key)
	w.line("func (u %s) MarshalJSON() ([]byte, error) {", t.Name)
	w.line("return marshalVariant(%s, u.Value)", key)
	w.line("}")
	w.line("")
	w.line("// UnmarshalJSON decodes the variant its %s tag names.", key)
	w.line("func (u *%s) UnmarshalJSON(b []byte) error {", t.Name)
	w.line("tag, null, err := variantTagOf(b, %s)", key)
	w.line("if err != nil {")
	w.line("return fmt.Errorf(%s, err)", strconv.Quote(t.Name+": %w"))
	w.line("}")
	w.line("if null {")
	w.line("u.Value = nil")
	w.line("return nil")
	w.line("}")
	w.line("switch tag {")
	for _, v := range t.Variants {
		w.line("case %s:", strconv.Quote(v.Tag))
		w.line("var v %s", v.GoName)
		w.line("err = json.Unmarshal(b, &v)")
		w.line("u.Value = v")
	}
	w.line("default:")
	w.line("u.Value = UnknownVariant{Tag: tag, Raw: append(json.RawMessage(nil), b...)}")
	w.line("}")
	w.line("return err")
	w.line("}")
	w.line("")
	w.line("func (UnknownVariant) is%s() {}", t.Name)
	for _, v := range t.Variants {
		w.line("")
		w.line("// %s is the %s variant of %s.", v.GoName, strconv.Quote(v.Tag), t.Name)
		if v.Doc != "" {
			w.line("//")
			w.doc(v.Doc)
		}
		w.structType(v.GoName, v.Fields)
		w.line("")
		w.line("func (%s) variantTag() string { return %s }", v.GoName, strconv.Quote(v.Tag))
		w.line("func (%s) is%s() {}", v.GoName, t.Name)
	}
}

func (w *writer) request(t *Type) {
	w.doc(t.Doc)
	if t.Doc != "" {
		w.line("//")
	}
	w.line("// %s is one API call. Decoding sets Params to the method's params", t.Name)
	w.line("// type (a value, not a pointer), or to json.RawMessage for a method the")
	w.line("// pinned schema does not list.")
	fields := append(append([]Field(nil), t.Fields...),
		Field{GoName: "Method", JSON: "method", GoType: "string"},
		Field{GoName: "Params", JSON: "params", GoType: "any"})
	w.structType(t.Name, fields)
	w.line("")
	w.line("// UnmarshalJSON decodes Params as the type Method names.")
	w.line("func (r *%s) UnmarshalJSON(b []byte) error {", t.Name)
	w.line("var head struct {")
	for _, f := range t.Fields {
		w.line("%s %s `json:%s`", f.GoName, f.GoType, strconv.Quote(f.JSON))
	}
	w.line("Method string `json:\"method\"`")
	w.line("Params json.RawMessage `json:\"params\"`")
	w.line("}")
	w.line("if err := json.Unmarshal(b, &head); err != nil {")
	w.line("return err")
	w.line("}")
	for _, f := range t.Fields {
		w.line("r.%s = head.%s", f.GoName, f.GoName)
	}
	w.line("r.Method = head.Method")
	w.line("var err error")
	w.line("switch head.Method {")
	for _, m := range t.Methods {
		w.line("case %s:", strconv.Quote(m.Name))
		w.line("var p %s", m.Params)
		w.line("err = unmarshalParams(head.Params, &p)")
		w.line("r.Params = p")
	}
	w.line("default:")
	w.line("r.Params = head.Params")
	w.line("}")
	w.line("if err != nil {")
	w.line("return fmt.Errorf(\"%%s params: %%w\", head.Method, err)")
	w.line("}")
	w.line("return nil")
	w.line("}")
}
